const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define city geometries with buffers
  const sanJose = ee.Geometry.Point([-121.8863, 37.3382]).buffer(15000); // 15km buffer
  const losAngeles = ee.Geometry.Point([-118.2437, 34.0522]).buffer(15000); // 15km buffer

  // Time period
  const startDate = '2018-01-01';
  const endDate = '2019-12-31';

  // Load Sentinel-5P NO2 data
  const no2Collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(startDate, endDate)
    .select('NO2_column_number_density');

  // Check collection size
  const collectionSize = no2Collection.size().getInfo();
  if (collectionSize === 0) {
    print("No NO2 data found for 2018-2019");
    print("<answer>C1</answer>");
    return;
  }

  // Calculate mean NO2 for both cities
  const meanNO2 = no2Collection.mean();

  // Calculate NO2 concentrations and valid pixel counts
  const sjStats = meanNO2.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), null, true),
    geometry: sanJose,
    scale: 1000,
    maxPixels: 1e9
  });

  const laStats = meanNO2.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), null, true),
    geometry: losAngeles,
    scale: 1000,
    maxPixels: 1e9
  });

  const sjResult = sjStats.getInfo();
  const laResult = laStats.getInfo();

  const sjNO2 = sjResult.NO2_column_number_density_mean;
  const laNO2 = laResult.NO2_column_number_density_mean;
  const sjPixels = sjResult.NO2_column_number_density_count;
  const laPixels = laResult.NO2_column_number_density_count;

  // Check for valid pixels
  if (sjPixels === 0 || laPixels === 0) {
    print(`San Jose pixels: ${sjPixels}, LA pixels: ${laPixels}`);
    print("<answer>C2</answer>");
    return;
  }

  // Validate results
  if (sjNO2 === null || laNO2 === null || isNaN(sjNO2) || isNaN(laNO2)) {
    print("Invalid NO2 values detected");
    print("<answer>C3</answer>");
    return;
  }

  // Print results and determine answer
  print(`San Jose NO2: ${sjNO2.toFixed(6)} mol/m² (${sjPixels} pixels)`);
  print(`Los Angeles NO2: ${laNO2.toFixed(6)} mol/m² (${laPixels} pixels)`);
  print(`Images in collection: ${collectionSize}`);

  if (sjNO2 > laNO2) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
